 foreach(array('simple','pages','branch','consent','random') as $variant)pe_case('Persistent engine/domain differential '.$variant,function()use($variant){global $wpdb;$p=pe_publish($variant);$http=pe_runtime()->handle($p['public']);$req=pe_request($http,'partial');$id=$req['execution_id'];$row=(new P\StudyExecutionRepository(new P\Database($wpdb)))->find($id);$graph=(new P\StudyVersionRepository(new P\Database($wpdb)))->compiled((new P\StudyVersionRepository(new P\Database($wpdb)))->find($p['version']));$pure=new Simulator($graph,array('created_at'=>str_replace(' ','T',$row['created_at']).'Z','execution_id'=>$id,'seed_hex'=>pe_vault()->open($id,$row['seed_key_id'],$row['seed_ciphertext']),'seed_ref'=>'SEED_'.$id));pe_equal($pure->snapshot(),pe_snapshot($id),'Initial differs');
